css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .72); position: relative; overflow: hidden; border-radius: 4px; background: radial-gradient(circle at 50% 62%, color-mix(in srgb, #fff 62%, var(--accent-2)) 0 20%, color-mix(in srgb, #000 44%, var(--accent-2)) 72%); }
.loader::before { content: ''; position: absolute; z-index: 3; top: 0; left: 0; width: 100%; height: 15%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 32%, var(--accent))); box-shadow: 0 2px 5px rgba(15, 23, 42, .35); }
.loader span { position: absolute; top: 0; height: 100%; width: 52%; background: repeating-linear-gradient(90deg, var(--accent) 0 7%, color-mix(in srgb, #000 28%, var(--accent)) 7% 14%); }
.loader span:nth-child(1) { left: 0; animation: part-left calc(var(--loader-speed) * 3.2) ease-in-out infinite; }
.loader span:nth-child(2) { right: 0; animation: part-right calc(var(--loader-speed) * 3.2) ease-in-out infinite; }
@keyframes part-left { 0%, 14% { transform: translateX(0); } 44%, 66% { transform: translateX(-86%); } 92%, 100% { transform: translateX(0); } }
@keyframes part-right { 0%, 14% { transform: translateX(0); } 44%, 66% { transform: translateX(86%); } 92%, 100% { transform: translateX(0); } }
